            let (_, portLanes) = unsafe withGuardedLanes(sentinel) { destination in
                unsafe H.store(a, to: destination)
            }
            let (_, referenceLanes) = unsafe withGuardedLanes(sentinel) { destination in
                unsafe HighwayReference.storeBlockI16(a.raw, destination)
            }
            mismatches.check(portLanes, referenceLanes, "a: \(describe(a))")
        }
        mismatches.record()
    }

    @Test func storeBlockUncheckedSpan() {
        let mismatches = Mismatches("storeBlock unchecked span")
        let aInputs = Inputs.vectors(H.BlockVector.self, seed: 0xE4EB_A51B_22E6_03ED).map(
            poisoningUpperBytes
        )
        let sentinel = Inputs.sentinel(H.Lane.self, count: 16 / MemoryLayout<H.Lane>.size + 4)
        for a in aInputs {
            var portLanes = sentinel
            portLanes.withUnsafeMutableBufferPointer { destination in
                ({
                    var span = unsafe MutableSpan(_unsafeElements: destination)
                    return unsafe H.store(a, toUnchecked: &span)
                })()
            }
            var referenceLanes = sentinel
            referenceLanes.withUnsafeMutableBufferPointer { destination in
                ({
                    var span = unsafe MutableSpan(_unsafeElements: destination)
